175	
176	    public EmailSender(SentMessages sentMessages) {
177	        this.sentMessages = sentMessages;
178	    }
179	
180	    public Message send(String to, String subject, String body) {
181	        return sentMessages.add("EMAIL", to, subject, body);
182	    }
183	}
